// Offline support, written by hand rather than generated by a build plugin: the whole thing is
// under a hundred lines, and this project deliberately carries no dependency it can avoid.
//
// Why it matters here specifically: mobile internet in Tajikistan ranks near the bottom worldwide,
// so a page that needs a working connection to show anything is a page that often shows nothing.
// With this, someone standing in a bank with one bar still sees the rates they loaded earlier.
//
// The rule that governs every decision below: a fresh answer always beats a cached one. Cached
// rates are a fallback for when the network fails, never a shortcut taken while it works — showing
// yesterday's numbers as though they were today's would be worse than showing nothing at all.

// Bumped to v2 when the static build arrived: a device still holding v1 caches would keep serving
// the old entries, and activate() only clears caches whose name does not end in the current
// version. Without the bump, offline visitors would sit on data that no longer has a source.
const VERSION = "v2";
const ASSET_CACHE = `bankrate-assets-${VERSION}`;
const PAGE_CACHE = `bankrate-pages-${VERSION}`;
const DATA_CACHE = `bankrate-data-${VERSION}`;

// Both shapes the same app can run in, listed together because one service worker serves both and
// a device cannot know which build it was given:
//   /api/*  — an Express process answers live (the server deployment)
//   /data/* — the same JSON, written to files at build time (the static deployment)
// Leaving the /data entries out is invisible while online and only surfaces with the network gone,
// which is exactly when this file is the only thing standing between a visitor and a blank page.
const CACHEABLE_API = [
  "/api/rates",
  "/api/rates/best",
  "/api/limits",
  "/api/banks",
  "/data/rates.json",
  "/data/rates-best.json",
  "/data/limits.json",
  "/data/banks.json"
];

self.addEventListener("install", (event) => {
  // Take over as soon as possible: a half-updated app is more confusing than a brief reload.
  self.skipWaiting();
  event.waitUntil(caches.open(ASSET_CACHE));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names
          .filter((name) => name.startsWith("bankrate-") && !name.endsWith(VERSION))
          .map((name) => caches.delete(name))
      );
      await self.clients.claim();
    })()
  );
});

function isImmutableAsset(url) {
  // Vite fingerprints these filenames, so a given URL's contents can never change.
  return url.pathname.startsWith("/assets/") || url.pathname === "/favicon.svg";
}

function isCacheableApi(url) {
  return CACHEABLE_API.some((path) => url.pathname === path);
}

// The CORS middleware stamps `Vary: Origin` on responses, and by default a cache lookup then
// demands that the incoming request carry the same Origin header. Same-origin requests for scripts
// and styles do not send one, so every lookup missed and the cache was silently useless — the
// failure only showed up with the network actually switched off. Nothing here genuinely varies by
// origin: one process serves one site.
const MATCH_OPTIONS = { ignoreVary: true };

async function cacheFirst(request, cacheName) {
  const cached = await caches.match(request, MATCH_OPTIONS);
  if (cached) {
    return cached;
  }

  const response = await fetch(request);
  if (response.ok) {
    const cache = await caches.open(cacheName);
    cache.put(request, response.clone());
  }
  return response;
}

async function networkFirst(request, cacheName) {
  try {
    const response = await fetch(request);

    if (response.ok) {
      const cache = await caches.open(cacheName);
      cache.put(request, response.clone());
    }

    return response;
  } catch (error) {
    const cached = await caches.match(request, MATCH_OPTIONS);
    if (cached) {
      // Marked so the page can tell the difference and say so out loud, instead of quietly
      // presenting old figures as current.
      const headers = new Headers(cached.headers);
      headers.set("X-Served-From-Cache", "1");
      return new Response(await cached.blob(), {
        status: cached.status,
        statusText: cached.statusText,
        headers
      });
    }
    throw error;
  }
}

self.addEventListener("fetch", (event) => {
  const { request } = event;

  if (request.method !== "GET") {
    return;
  }

  const url = new URL(request.url);

  if (url.origin !== self.location.origin) {
    return;
  }

  // The admin panel and its data never go into a device cache: it is behind a key, and a cached
  // copy would outlive the session that was allowed to see it.
  if (url.pathname.startsWith("/admin") || url.pathname.startsWith("/api/admin")) {
    return;
  }

  if (isImmutableAsset(url)) {
    event.respondWith(cacheFirst(request, ASSET_CACHE));
    return;
  }

  if (isCacheableApi(url)) {
    event.respondWith(networkFirst(request, DATA_CACHE));
    return;
  }

  // Page navigations. The HTML carries server-rendered rates, so it is worth keeping a copy for
  // the offline case, but the network always gets first refusal.
  if (request.mode === "navigate") {
    event.respondWith(networkFirst(request, PAGE_CACHE));
  }
});
